function getHeader(list, name) {
  if (!Array.isArray(list)) return '';
  const found = list.find((h) => String(h.name || '').toLowerCase() === name.toLowerCase());
  return found ? (found.value || '') : '';
}

// Gmail devuelve "internalDate" como TEXTO (ej. "1788674661000"). new
// Date() con un string numérico no lo toma como milisegundos: intenta
// leerlo como fecha y revienta con "Invalid time value". Por eso se
// prueba primero como número antes de dejar que Date lo interprete.
function parseFlexibleDate(value) {
  if (!value) return new Date();
  const asNumber = Number(value);
  if (!Number.isNaN(asNumber) && asNumber > 0) return new Date(asNumber);
  const asDate = new Date(value);
  return Number.isNaN(asDate.getTime()) ? new Date() : asDate;
}

// Distintas versiones/formatos del Gmail Trigger de n8n exponen el
// remitente y el asunto de maneras distintas (campos planos en
// minúscula, con mayúscula inicial, o solo dentro de payload.headers).
// Antes esto asumía un único formato y, si no coincidía, guardaba el
// correo con remitente/asunto vacíos ('--' en el CRM).
const headers = ($json.payload && $json.payload.headers) || $json.headers || [];
const fromRaw = $json.from || $json.From || getHeader(headers, 'From') || '';
const subjectRaw = $json.subject || $json.Subject || getHeader(headers, 'Subject') || '';

const emailMatch = fromRaw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const nameMatch = fromRaw.match(/^(.*)<(.+)>$/);
const fromName = nameMatch ? nameMatch[1].trim().replace(/^"|"$/g, '') : (emailMatch ? fromRaw.replace(emailMatch[0], '').replace(/[<>\(\)"]+/g, '').trim() : fromRaw);
const fromEmail = nameMatch ? nameMatch[2].trim() : (emailMatch ? emailMatch[0] : '');
const rawDate = $json.date || $json.internalDate || $json.receivedAt || getHeader(headers, 'Date');
const receivedAt = parseFlexibleDate(rawDate).toISOString();

return [
  {
    json: {
      id: $json.id || $json.messageId || $json.message_id || '',
      source: 'gmail',
      label: 'negocios',
      from_name: fromName,
      from_email: fromEmail,
      subject: subjectRaw,
      snippet: $json.snippet || '',
      body: $json.snippet || '',
      message_id: $json.id || $json.messageId || $json.message_id || '',
      thread_id: $json.threadId || $json.thread_id || '',
      received_at: receivedAt,
      url: $json.webViewLink || '',
      raw: $json
    }
  }
];
